function boundaryElements(matrix) {
  if (!matrix.length) return [];
  const result = [];
  const rows = matrix.length, cols = matrix[0].length;
  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      if (i === 0 || i === rows-1 || j === 0 || j === cols-1) {
        result.push(matrix[i][j]);
      }
    }
  }
  return result;
}
